alter policy "Owners read audio" on storage.objects using(bucket_id='project-audio' and ((storage.foldername(objects.name))[1]=(select auth.uid())::text or exists(select 1 from public.projects p where p.id::text=(storage.foldername(objects.name))[2] and p.owner_id::text=(storage.foldername(objects.name))[1] and public.project_access(p.id,false))));
alter policy "Owners upload audio" on storage.objects with check(bucket_id='project-audio' and ((storage.foldername(objects.name))[1]=(select auth.uid())::text or exists(select 1 from public.projects p where p.id::text=(storage.foldername(objects.name))[2] and p.owner_id::text=(storage.foldername(objects.name))[1] and public.project_access(p.id,true))));
